import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class Solution {

    public record Item(int producerId, int sequence) {
    }

    public record PipelineResult(long produced, long consumed, long duplicates,
                                 long checksum, boolean gracefulShutdown,
                                 long elapsedMillis) {
    }

    static final Item POISON = new Item(-1, -1);

    public static PipelineResult run(int producers, int consumers, int itemsPerProducer,
                                     int capacity, Duration timeout)
            throws InterruptedException {
        if (producers < 1) {
            throw new IllegalArgumentException("producers deve ser >= 1");
        }
        if (consumers < 1) {
            throw new IllegalArgumentException("consumers deve ser >= 1");
        }
        if (itemsPerProducer < 0) {
            throw new IllegalArgumentException("itemsPerProducer deve ser >= 0");
        }
        if (capacity < 1) {
            throw new IllegalArgumentException("capacity deve ser >= 1");
        }
        if (timeout == null || timeout.isZero() || timeout.isNegative()) {
            throw new IllegalArgumentException("timeout deve ser positivo");
        }

        BlockingQueue<Item> queue = new ArrayBlockingQueue<>(capacity);
        LongAdder consumed = new LongAdder();
        AtomicLong checksum = new AtomicLong();
        AtomicLong duplicates = new AtomicLong();
        Set<Long> seen = ConcurrentHashMap.newKeySet();

        List<Thread> producerThreads = new ArrayList<>(producers);
        List<Thread> consumerThreads = new ArrayList<>(consumers);
        long start = System.nanoTime();

        for (int p = 0; p < producers; p++) {
            int producerId = p;
            producerThreads.add(Thread.ofPlatform().name("producer-" + p).start(() -> {
                try {
                    for (int i = 0; i < itemsPerProducer; i++) {
                        queue.put(new Item(producerId, i));
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }));
        }

        for (int c = 0; c < consumers; c++) {
            consumerThreads.add(Thread.ofPlatform().name("consumer-" + c).start(() -> {
                try {
                    while (true) {
                        Item item = queue.take();
                        if (item == POISON) {
                            return;
                        }
                        long key = ((long) item.producerId() << 32)
                                | (item.sequence() & 0xffff_ffffL);
                        if (!seen.add(key)) {
                            duplicates.incrementAndGet();
                        }
                        consumed.increment();
                        checksum.addAndGet(item.sequence());
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }));
        }

        for (Thread producer : producerThreads) {
            producer.join();
        }
        for (int c = 0; c < consumers; c++) {
            queue.put(POISON);
        }

        long deadline = System.nanoTime() + timeout.toNanos();
        boolean graceful = true;
        for (Thread consumer : consumerThreads) {
            long remaining = deadline - System.nanoTime();
            if (remaining > 0) {
                consumer.join(TimeUnit.NANOSECONDS.toMillis(remaining) + 1);
            }
            if (consumer.isAlive()) {
                graceful = false;
                consumer.interrupt();
            }
        }

        long elapsedMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        long expectedChecksum = (long) producers * itemsPerProducer
                * (itemsPerProducer - 1) / 2;
        return new PipelineResult((long) producers * itemsPerProducer,
                consumed.sum(), duplicates.get(), checksum.get(), graceful, elapsedMillis);
    }
}

