import org.junit.jupiter.api.Test;

import java.time.Duration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SolutionTest {

    private static final Duration TIMEOUT = Duration.ofSeconds(5);

    @Test
    void caminhoFelizConsomeCadaItemUmaVez() throws Exception {
        Solution.PipelineResult result = Solution.run(2, 4, 1_000, 16, TIMEOUT);

        assertEquals(2_000, result.produced());
        assertEquals(2_000, result.consumed());
        assertEquals(0, result.duplicates());
        assertEquals(999_000, result.checksum());
        assertTrue(result.gracefulShutdown());
        assertTrue(result.elapsedMillis() >= 0);
    }

    @Test
    void capacidadeUmNaoCausaDeadlock() throws Exception {
        Solution.PipelineResult result = Solution.run(1, 1, 500, 1, TIMEOUT);

        assertEquals(500, result.produced());
        assertEquals(500, result.consumed());
        assertEquals(124_750, result.checksum());
        assertTrue(result.gracefulShutdown());
    }

    @Test
    void semItensOsConsumidoresEncerramComVeneno() throws Exception {
        Solution.PipelineResult result = Solution.run(3, 2, 0, 1, TIMEOUT);

        assertEquals(0, result.produced());
        assertEquals(0, result.consumed());
        assertEquals(0, result.checksum());
        assertTrue(result.gracefulShutdown());
    }

    @Test
    void muitosProdutoresEConsumidores() throws Exception {
        Solution.PipelineResult result = Solution.run(8, 8, 2_000, 32, TIMEOUT);

        assertEquals(16_000, result.produced());
        assertEquals(16_000, result.consumed());
        assertEquals(0, result.duplicates());
        assertEquals(8L * 2_000 * 1_999 / 2, result.checksum());
    }

    @Test
    void parametrosInvalidosFalhamAntesDeCriarThreads() {
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(0, 1, 10, 1, TIMEOUT));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(1, 0, 10, 1, TIMEOUT));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(1, 1, -1, 1, TIMEOUT));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(1, 1, 10, 0, TIMEOUT));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(1, 1, 10, 1, Duration.ZERO));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.run(1, 1, 10, 1, null));
    }

    @Test
    void threadsSaoEncerradasAoFinal() throws Exception {
        Solution.run(2, 2, 100, 4, TIMEOUT);
        long alive = Thread.getAllStackTraces().keySet().stream()
                .filter(t -> t.getName().startsWith("producer-")
                        || t.getName().startsWith("consumer-"))
                .filter(Thread::isAlive)
                .count();
        assertEquals(0, alive);
    }

    @Test
    void timeoutCurtoAindaConcluiTrabalhoPequeno() throws Exception {
        Solution.PipelineResult result = Solution.run(1, 1, 10, 1, Duration.ofMillis(200));
        assertEquals(10, result.consumed());
        assertTrue(result.gracefulShutdown());
        assertFalse(result.elapsedMillis() > 5_000);
    }
}
